<script>
 import {untrack} from 'svelte';
 import {workflowHref} from '../../lib/workflow-location.js';
 let {state:workspace,location,planIds,positions,request,onSaved,onNavigate,onRestoreView,onDirtyChange=()=>{}}=$props();
 let reportsOpen=$state(false),notesOpen=$state(false);
 $effect(()=>{if(location.view==='report')reportsOpen=true;});
 $effect(()=>{if(location.selected)notesOpen=true;});
 let groupName=$state(''),destinationName=$state(''),destinationId=$state(''),objective=$state(''),deliverables=$state(''),savedDraft=$state(null);
 let noteTarget=$state(''),note=$state(''),noteKind=$state('note'),viewName=$state(''),title=$state(''),thesis=$state('');
 let busy=$state(false),error=$state(''),notice=$state(''),intent=$state(null),unknown=$state(false),loadedReport=$state(''),loadedReportRevision=$state(0),baseTitle=$state(''),baseThesis=$state(''),historyIndex=$state('current');
 const report=$derived(workspace.reports.find(r=>r.id===location.reportId));
 const selectedNotes=$derived(workspace.annotations.filter(a=>a.targetId===location.selected));
 const wordingDirty=$derived(title!==baseTitle||thesis!==baseThesis);
 const groupMembers=$derived(planIds.filter(id=>workspace.graph.nodes.some(n=>n.id===id)));
 const dirty=$derived(Boolean(groupName.trim()||destinationName.trim()||objective.trim()||deliverables.trim()||note.trim()||viewName.trim()||title!==baseTitle||thesis!==baseThesis||intent));
 $effect(()=>{onDirtyChange(dirty);});
 $effect(()=>{const id=report?.id||'',revision=report?.revision||0;untrack(()=>{if((id!==loadedReport||revision!==loadedReportRevision)&&!wordingDirty&&!intent)adoptReport(false);});});
 function adoptReport(keepWording){loadedReport=report?.id||'';loadedReportRevision=report?.revision||0;historyIndex='current';baseTitle=report?.title||'';baseThesis=report?.thesis||'';if(!keepWording){title=baseTitle;thesis=baseThesis;}intent=null;error='';}
 function edit(){notice='';if(!unknown)intent=null;}
 function editNote(event){const value=event.currentTarget.value;if(value.trim()&&!noteTarget)noteTarget=location.selected;if(!value.trim())noteTarget='';note=value;edit();}
 async function send(path,payload,kind){
  if(busy||unknown)return;intent={path,body:{expectedRevision:workspace.revision,idempotencyKey:crypto.randomUUID(),...payload},kind};await submit();
 }
 async function submit(){
  if(!intent||busy)return;busy=true;error='';notice='';
  try{const ack=await request(intent.path,{method:'POST',body:JSON.stringify(intent.body)});const kind=intent.kind;intent=null;unknown=false;
   if(kind==='group'){groupName='';onNavigate({...location,view:'map',focus:ack.cluster.id,selected:ack.cluster.id});}if(kind==='destination'){destinationId=ack.destination.id;destinationName='';}if(kind==='handoff'){savedDraft=ack.draft;objective='';deliverables='';}if(kind==='note'){note='';noteTarget='';}if(kind==='view')viewName='';if(kind==='report'){title=ack.report.title;thesis=ack.report.thesis;baseTitle=title;baseThesis=thesis;loadedReport=ack.report.id;loadedReportRevision=ack.report.revision;onNavigate({...location,view:'report',reportId:ack.report.id});}
   notice=kind==='group'?'Working group saved':kind==='destination'?'Draft destination created':kind==='handoff'?'Draft created. Source review is still required.':kind==='refresh'?'Saved a new report snapshot':kind==='note'?'Note saved':kind==='view'?'View saved':'Report saved';try{await onSaved(ack);}catch{error='Your save succeeded, but current references could not reload. Reload to see the saved version.';}
  }catch(failure){error=failure.status===409?'The workspace changed. Your text is retained. Reload current references, then save again.':failure.message;unknown=!(Number.isInteger(failure.status)&&failure.status>=400&&failure.status<500);}
  finally{busy=false;}
 }
 async function reload(){if(busy||unknown)return;intent=null;try{await onSaved();}catch(failure){error=failure.message;}}
 function draftHref(draft){return workflowHref(window.location.href,{organizationId:draft.organizationId,brandId:draft.brandId,tab:'studio',storyId:draft.id,format:'infographic'});}
 function openView(view){if(dirty){error='Save or clear your working text before opening another view.';return;}onRestoreView(view);}
 function openReport(id){if(dirty){error='Save or clear your working text before opening a report.';return;}onNavigate({...location,view:'report',reportId:id});}
</script>
<section class="planning" aria-label="Shared planning">
 <button class="quiet" disabled={busy||unknown} onclick={reload}>Reload saved work</button>
 {#if error}<p role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if unknown}<p>The reply was interrupted. Retry this same save to check its outcome.</p><button disabled={busy} onclick={submit}>Retry same save</button>{:else if error}<button disabled={busy} onclick={reload}>Reload current references</button>{/if}
 <details bind:open={notesOpen}><summary>Notes on this selection <span>{selectedNotes.length}</span></summary>
 {#if location.selected}<div class="notes">{#each selectedNotes as saved(saved.id)}<article><strong>{saved.kind}</strong><p>{saved.text}</p><small>Saved · revision {saved.revision}</small></article>{/each}</div>
 <label>Note type<select bind:value={noteKind} disabled={busy||unknown}><option value="note">Note</option><option value="question">Question</option><option value="hypothesis">Hypothesis</option><option value="decision">Decision</option></select></label>{#if noteTarget&&noteTarget!==location.selected}<p>Your working note remains attached to {workspace.items.find(item=>item.id===noteTarget)?.name||'its original selection'}.</p>{/if}<label>Your note<textarea value={note} oninput={editNote} disabled={busy||unknown} rows="3" maxlength="6000"></textarea></label><button disabled={busy||unknown||!note.trim()} onclick={()=>send('/annotations',{annotation:{targetId:noteTarget||location.selected,kind:noteKind,text:note}},'note')}>Save note</button>{:else}<p>Select a reference or relationship to add a shared note.</p>{/if}</details>
 <details><summary>Working groups <span>{workspace.graph.clusters.length}</span></summary><p>A working selection, not a claim that these people have agreed to collaborate.</p><div class="saved-list">{#each workspace.graph.clusters as group(group.id)}<button disabled={busy||unknown||dirty} onclick={()=>onNavigate({...location,view:'map',focus:group.id,selected:group.id})}>{group.name} · {group.nodeIds.length}</button>{/each}</div><label>Name this working group<input bind:value={groupName} oninput={edit} disabled={busy||unknown} maxlength="200"/></label><p>{groupMembers.length} shortlisted references will be included. Relationships stay separate.</p><button disabled={busy||unknown||!groupName.trim()||!groupMembers.length} onclick={()=>send('/clusters',{cluster:{name:groupName,nodeIds:groupMembers}},'group')}>Save working group</button></details>
 <details><summary>Saved views <span>{workspace.views.length}</span></summary><div class="saved-list">{#each workspace.views as view(view.id)}<button disabled={busy||unknown} onclick={()=>openView(view)}>{view.name}</button>{/each}</div><label>Name this view<input bind:value={viewName} oninput={edit} disabled={busy||unknown} maxlength="200"/></label><button disabled={busy||unknown||!viewName.trim()} onclick={()=>send('/views',{view:{name:viewName,focus:location.focus,selected:location.selected,planIds,positions}},'view')}>Save current view</button></details>
 <details bind:open={reportsOpen}><summary>Reports <span>{workspace.reports.length}</span></summary><div class="saved-list">{#each workspace.reports as saved(saved.id)}<button disabled={busy||unknown} onclick={()=>openReport(saved.id)}>{saved.title}</button>{/each}</div>
 {#if location.view==='report'&&location.reportId&&!report}<p>This report is unavailable in the current organization.</p>{/if}
 {#if report}{@const snapshot=historyIndex==='current'?report:(report.history[Number(historyIndex)]||report)}<article class="report"><label>Read a report version<select bind:value={historyIndex}><option value="current">Current · revision {report.revision}</option>{#each report.history as previous,index(previous.revision)}<option value={String(index)}>Earlier · revision {previous.revision}</option>{/each}</select></label><h3>{snapshot.title}</h3><p>{snapshot.thesis}</p><small>Snapshot revision {snapshot.revision} · source revision {snapshot.sourceRevision}. Changes to references do not update this report automatically.</small>{#each snapshot.findings as finding(finding.id)}<section><h4>{finding.name}</h4><p>{finding.description}</p>{#each finding.notes as saved(saved.id)}<blockquote>{saved.text}</blockquote>{/each}{#each finding.evidence as evidence(evidence.id)}<p>{evidence.title}{#if evidence.sourceUrl} · <a href={evidence.sourceUrl} target="_blank" rel="noopener noreferrer">Source</a>{/if}</p>{/each}</section>{/each}{#if snapshot.annotations?.length}<details><summary>Included notes</summary>{#each snapshot.annotations as saved(saved.id)}<p>{saved.text}</p>{/each}</details>{/if}<p>{report.history.length} earlier snapshots retained.</p><button disabled={busy||unknown||!planIds.length} onclick={()=>send(`/reports/${report.id}/refresh`,{expectedReportRevision:report.revision,planIds},'refresh')}>Refresh from current shortlist</button><button disabled={busy||unknown||dirty} onclick={()=>onNavigate({...location,view:'map',reportId:''})}>Back to map</button></article>{/if}
 {#if report&&report.id===loadedReport&&report.revision!==loadedReportRevision}<section class="version-conflict" aria-label="Newer report wording"><h3>A newer report version is saved</h3><p>Your working text is still based on revision {loadedReportRevision}. Saved revision {report.revision}: {report.title}</p><p>{report.thesis}</p><button disabled={busy||unknown} onclick={()=>adoptReport(false)}>Use saved wording</button><button disabled={busy||unknown} onclick={()=>adoptReport(true)}>Keep my wording on this version</button></section>{/if}
 {#if report}<p>Wording below edits the current report. Earlier snapshots stay unchanged.</p>{/if}<label>Report title<input bind:value={title} oninput={edit} disabled={busy||unknown} maxlength="300"/></label><label>Working thesis<textarea bind:value={thesis} oninput={edit} disabled={busy||unknown} rows="3" maxlength="12000"></textarea></label>
 <button disabled={busy||unknown||!title.trim()||(!report&&!planIds.length)} onclick={()=>send('/reports',{report:{...(report?{id:report.id,expectedReportRevision:loadedReportRevision}:{planIds}),title,thesis}},'report')}>{report?'Save report wording':'Save shortlist as report'}</button><p>{report?'Saving wording preserves the findings snapshot. Refresh only when you want to capture current references.':'Choose at least one finding for your shortlist. Reports retain the evidence and notes from the time you save.'}</p>
 {#if report}<details class="handoff"><summary>Create a draft from this report</summary><p>Uses current saved report revision {report.revision}. Choose where this brief belongs. This creates a draft for source review; it does not publish or approve the report.</p><label>Draft destination<select value={destinationId||location.destinationBrandId} onchange={e=>{destinationId=e.currentTarget.value;edit();onNavigate({...location,destinationBrandId:destinationId});}} disabled={busy||unknown}><option value="">Choose a destination</option>{#each workspace.destinations as destination(destination.id)}<option value={destination.id}>{destination.name}</option>{/each}</select></label><details><summary>Create a separate draft destination</summary><label>Destination name<input bind:value={destinationName} oninput={edit} disabled={busy||unknown} maxlength="200"/></label><button disabled={busy||unknown||!destinationName.trim()} onclick={()=>send('/destinations',{name:destinationName},'destination')}>Create draft destination</button><p>No social account is connected by this action.</p></details><label>Objective<textarea bind:value={objective} oninput={edit} disabled={busy||unknown} rows="2" maxlength="2000"></textarea></label><label>Proposed deliverables, one per line (up to 16)<textarea bind:value={deliverables} oninput={edit} disabled={busy||unknown} rows="3"></textarea></label><button disabled={busy||unknown||!objective.trim()||!deliverables.trim()||!(destinationId||location.destinationBrandId)||wordingDirty||historyIndex!=='current'} onclick={()=>send(`/reports/${report.id}/handoff`,{expectedReportRevision:report.revision,destinationId:destinationId||location.destinationBrandId,objective,deliverables:deliverables.split('\n').map(value=>value.trim()).filter(Boolean)},'handoff')}>Create review-required draft</button>{#if historyIndex!=='current'}<p>Choose the current report version before creating a draft.</p>{/if}{#if wordingDirty}<p>Save or clear report wording before creating a draft from its saved version.</p>{/if}</details>{/if}
 </details>
 {#if savedDraft}<section class="handoff-result" aria-label="Created draft"><h3>{savedDraft.title}</h3><p>Draft created with this report snapshot, your objective and proposed deliverables. Source review is required.</p><a href={draftHref(savedDraft)}>Open draft in Campaign Studio →</a></section>{/if}
 {#if dirty&&!unknown}<button class="quiet" disabled={busy} onclick={()=>{groupName='';destinationName='';objective='';deliverables='';note='';noteTarget='';viewName='';title=baseTitle;thesis=baseThesis;intent=null;error='';}}>Clear working text</button>{/if}
</section>
<style>
.planning{padding:16px 20px;border-top:1px solid #dedfd8;background:#fcfcf9;font-size:12px}.planning>details{padding:10px 0;border-bottom:1px solid #e4e6df}.planning summary{cursor:pointer;font-weight:650}.planning summary span{font-weight:400;color:#69765f;margin-left:6px}.planning label{display:block;margin:12px 0 6px}.planning textarea,.planning input,.planning select{display:block;width:100%;margin-top:5px;font:inherit}.planning button{margin:8px 8px 0 0}.planning p{line-height:1.65}.notes article,.report section{border-left:2px solid #bdcbb4;padding-left:12px;margin:12px 0}.saved-list{display:flex;gap:6px;flex-wrap:wrap}.report{padding-top:12px}.report h3{font-size:20px}.report small{color:#69765f}.planning blockquote{margin:8px 0;color:#596a51}.quiet{background:transparent}
</style>
